{#- Code generated by xgen. DO NOT EDIT.
    Source: xgen/specs/organisms/stat-figure.json
    One key number of StatsBand: a card (StatTile), or the value over its label, optionally under a Lucide icon.
    Props (p): stat, item, align. -#}
{%- set v_stat = (p.stat ?? null) -%}
{%- set v_item = (p.item ?? 'plain') -%}
{%- set v_align = (p.align ?? 'center') -%}
{%- if ui_t(ui_eq(v_item, 'card')) %}
  {{ include('blocks/stat-tile.html.twig', {'p': {'label': ui_get(v_stat, ['label']), 'value': ui_get(v_stat, ['value']), 'icon': ui_get(v_stat, ['icon']), 'hint': ui_get(v_stat, ['hint'])}}, with_context = false) }}
{%- else %}
  {%- set c_4 -%}
    {%- if ui_t(ui_eq(v_item, 'icon')) %}
      {{ include('ui/lucide-icon/lucide-icon.html.twig', {'p': {'Name': ui_s(ui_get(v_stat, ['icon'])), 'Size': 24}}, with_context = false) }}
    {%- endif %}
    {%- set c_3 -%}
      {%- set c_1 -%}
        {{ ui_text(ui_get(v_stat, ['value'])) }}
      {%- endset -%}
      {{ include('ui/text/text.html.twig', {'p': {'Size': '5xl', 'Weight': 'medium', 'Class': ui_s(ui_cnv(['flex items-center', ui_preset('blocks/presets/defaults.json', ['stats', 'figure'])]))}, 'children': c_1}, with_context = false) }}
      {%- set c_2 -%}
        {{ ui_text(ui_get(v_stat, ['label'])) }}
      {%- endset -%}
      {{ include('ui/text/text.html.twig', {'p': {'Size': 'sm', 'Weight': 'semibold', 'Class': 'leading-5 text-muted-foreground'}, 'children': c_2}, with_context = false) }}
    {%- endset -%}
    {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '2', 'Align': ui_s((ui_t(ui_eq(v_align, 'center')) ? 'center' : 'start'))}, 'children': c_3}, with_context = false) }}
  {%- endset -%}
  {{ include('ui/stack/stack.html.twig', {'p': {'Gap': '6', 'Align': ui_s((ui_t(ui_eq(v_align, 'center')) ? 'center' : 'start')), 'Class': ui_s(ui_cnv([(ui_t(ui_eq(v_align, 'center')) ? 'text-center' : ''), ui_preset('blocks/presets/defaults.json', ['stats', 'column'])])), 'Attrs': ui_attrs(['data-testid', 'item'])}, 'children': c_4}, with_context = false) }}
{%- endif %}
